  boolean lateBlocked=false;try{s.ui(()->{s.guardPath(after,pos[0],pos[1],pos[0],pos[1]);return true;});}catch(ControlService.KeyboardOcclusionException expected){lateBlocked=true;}yes(lateBlocked&&clicks.get()==1,"New keyboard bypassed old screenshot masks");passed++;report.put("late_keyboard_blocked",true);
